package com.learnagent.memory;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/memory-reviews")public class MemoryReviewController{private final MemoryReviewService service;public MemoryReviewController(MemoryReviewService service){this.service=service;}@GetMapping("/due")public List<MemoryDtos.CardView>due(@RequestParam(required=false)UUID courseId){return service.due(courseId);}@PostMapping("/sessions")public ResponseEntity<MemoryDtos.ReviewSessionView>start(@RequestBody(required=false)MemoryDtos.StartReviewRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.start(request==null?new MemoryDtos.StartReviewRequest(null):request));}@GetMapping("/sessions/{id}")public MemoryDtos.ReviewSessionView session(@PathVariable UUID id){return service.getSession(id);}@PostMapping("/sessions/{sessionId}/cards/{cardId}")public MemoryDtos.ReviewResult review(@PathVariable UUID sessionId,@PathVariable UUID cardId,@RequestBody MemoryDtos.ReviewRequest request){return service.review(sessionId,cardId,request);}@GetMapping("/statistics")public MemoryDtos.MemoryStatistics statistics(){return service.statistics();}}
